#!/usr/bin/env python
"""Regenerate checked-in SM3 bytecode. Normal builds need no shader compiler."""

import argparse
import re
import struct
import subprocess
import tempfile
from pathlib import Path


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--fxc", required=True, help="Path to the DirectX fxc shader compiler")
    parser.add_argument("--check", action="store_true", help="Verify checked-in bytecode without rewriting it")
    args = parser.parse_args()
    folder = Path(__file__).resolve().parent
    output = [
        "// Generated by generate_shaders.py from lighting.hlsl and shadow.hlsl. Do not edit bytecode.\n",
        '#include "lighting_bytecode.h"\n',
        "\n// clang-format off\n",
    ]
    with tempfile.TemporaryDirectory(prefix="godot_d3d9_shaders_") as temporary:
        assert Path(temporary).resolve().parent == Path(tempfile.gettempdir()).resolve()
        for name, target, entry, defines in [
            ("VERTEX", "vs_3_0", "vertex_main", ["VERTEX_SHADER=1"]),
            ("VERTEX_GEOMETRY", "vs_3_0", "vertex_main", ["VERTEX_SHADER=1", "GEOMETRY_SHADER=1"]),
            ("VERTEX_NORMAL_MAP", "vs_3_0", "vertex_main", ["VERTEX_SHADER=1", "GEOMETRY_SHADER=1", "NORMAL_MAP=1"]),
            ("VERTEX_TRANSIENT_NORMAL_MAP", "vs_3_0", "vertex_main", ["VERTEX_SHADER=1", "NORMAL_MAP=1"]),
            (
                "VERTEX_TRANSIENT_NORMAL_OCCLUSION",
                "vs_3_0",
                "vertex_main",
                ["VERTEX_SHADER=1", "NORMAL_MAP=1", "OCCLUSION_MAP=1"],
            ),
            ("PIXEL_NORMAL_MAP", "ps_3_0", "pixel_main", ["NORMAL_MAP=1"]),
            ("PIXEL_TEXTURED_NORMAL_MAP", "ps_3_0", "pixel_main", ["TEXTURED=1", "NORMAL_MAP=1"]),
            ("PIXEL", "ps_3_0", "pixel_main", []),
            ("PIXEL_TEXTURED", "ps_3_0", "pixel_main", ["TEXTURED=1"]),
            (
                "VERTEX_NORMAL_OCCLUSION",
                "vs_3_0",
                "vertex_main",
                ["VERTEX_SHADER=1", "GEOMETRY_SHADER=1", "NORMAL_MAP=1", "OCCLUSION_MAP=1"],
            ),
            ("PIXEL_NORMAL_OCCLUSION", "ps_3_0", "pixel_main", ["NORMAL_MAP=1", "OCCLUSION_MAP=1"]),
            (
                "PIXEL_TEXTURED_NORMAL_OCCLUSION",
                "ps_3_0",
                "pixel_main",
                ["TEXTURED=1", "NORMAL_MAP=1", "OCCLUSION_MAP=1"],
            ),
            ("VERTEX_TRANSIENT_OCCLUSION", "vs_3_0", "vertex_main", ["VERTEX_SHADER=1", "OCCLUSION_MAP=1"]),
            ("VERTEX_OCCLUSION", "vs_3_0", "vertex_main", ["VERTEX_SHADER=1", "GEOMETRY_SHADER=1", "OCCLUSION_MAP=1"]),
            ("PIXEL_OCCLUSION", "ps_3_0", "pixel_main", ["OCCLUSION_MAP=1"]),
            ("PIXEL_TEXTURED_OCCLUSION", "ps_3_0", "pixel_main", ["TEXTURED=1", "OCCLUSION_MAP=1"]),
            ("SHADOW_VERTEX", "vs_3_0", "vertex_main", ["VERTEX_SHADER=1"]),
            ("SHADOW_PIXEL", "ps_3_0", "pixel_main", []),
            ("SHADOW_PIXEL_TEXTURED", "ps_3_0", "pixel_main", ["TEXTURED=1"]),
            ("PIXEL_SHADOW", "ps_3_0", "pixel_main", ["DIRECTIONAL_SHADOW=1"]),
            ("PIXEL_TEXTURED_SHADOW", "ps_3_0", "pixel_main", ["DIRECTIONAL_SHADOW=1", "TEXTURED=1"]),
            ("PIXEL_NORMAL_SHADOW", "ps_3_0", "pixel_main", ["DIRECTIONAL_SHADOW=1", "NORMAL_MAP=1"]),
            (
                "PIXEL_TEXTURED_NORMAL_SHADOW",
                "ps_3_0",
                "pixel_main",
                ["DIRECTIONAL_SHADOW=1", "NORMAL_MAP=1", "TEXTURED=1"],
            ),
            ("PIXEL_OCCLUSION_SHADOW", "ps_3_0", "pixel_main", ["DIRECTIONAL_SHADOW=1", "OCCLUSION_MAP=1"]),
            (
                "PIXEL_TEXTURED_OCCLUSION_SHADOW",
                "ps_3_0",
                "pixel_main",
                ["DIRECTIONAL_SHADOW=1", "OCCLUSION_MAP=1", "TEXTURED=1"],
            ),
            (
                "PIXEL_NORMAL_OCCLUSION_SHADOW",
                "ps_3_0",
                "pixel_main",
                ["DIRECTIONAL_SHADOW=1", "NORMAL_MAP=1", "OCCLUSION_MAP=1"],
            ),
            (
                "PIXEL_TEXTURED_NORMAL_OCCLUSION_SHADOW",
                "ps_3_0",
                "pixel_main",
                ["DIRECTIONAL_SHADOW=1", "NORMAL_MAP=1", "OCCLUSION_MAP=1", "TEXTURED=1"],
            ),
        ]:
            binary = Path(temporary) / (name + ".bin")
            listing = Path(temporary) / (name + ".asm")
            command = [
                args.fxc,
                "/nologo",
                "/O3",
                "/T",
                target,
                "/E",
                entry,
                "/Fo",  # codespell:ignore fo
                str(binary),
                "/Fc",
                str(listing),
            ]
            for define in defines:
                command += ["/D", define]
            command.append(str(folder / ("shadow.hlsl" if name.startswith("SHADOW_") else "lighting.hlsl")))
            subprocess.run(command, check=True)
            slots = re.search(r"approximately (\d+) instruction slots used", listing.read_text())
            if slots is None:
                parser.exit(1, f"Cannot verify the static instruction budget for {name}.\n")
            # Every SM3 implementation guarantees 512 static slots; larger programs
            # would unnecessarily raise the old-hardware baseline of these variants.
            if int(slots.group(1)) > 512:
                parser.exit(1, f"{name} exceeds the 512-slot SM3 baseline.\n")
            print(f"{name}: {slots.group(1)} instruction slots")
            data = binary.read_bytes()
            words = struct.unpack(f"<{len(data) // 4}I", data)
            output.append(f"\nconst uint32_t FixedFunctionShadersD3D9::{name}[] = {{\n")
            for index in range(0, len(words), 8):
                output.append("\t" + ", ".join(f"0x{word:08x}" for word in words[index : index + 8]) + ",\n")
            output.append("};\n")
    output.append("\n// clang-format on\n")
    bytecode = "".join(output).encode("utf-8")
    destination = folder / "lighting_bytecode.cpp"
    if args.check:
        if destination.read_bytes() != bytecode:
            parser.exit(1, "Checked-in lighting bytecode is out of date.\n")
        print("Checked-in lighting bytecode matches the source.")
    else:
        destination.write_bytes(bytecode)


if __name__ == "__main__":
    main()
